<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $query=function_exists('nvconsult_v2_get_featured_jobs')?nvconsult_v2_get_featured_jobs(8):new WP_Query(array('post_type'=>'nvconsult_job','post_status'=>'publish','posts_per_page'=>8)); ?>
<section class="section"><div class="section-inner"><?php nvconsultv2_render_section_heading( 'featured-jobs', __( 'Featured Jobs', 'nvconsult-theme-v2' ), __( 'Latest work opportunities with transparent details.', 'nvconsult-theme-v2' ) ); ?><?php if($query->have_posts()): ?><div class="jobs-grid"><?php while($query->have_posts()): $query->the_post(); $location=get_post_meta(get_the_ID(),'_nvconsult_location',true); $salary=get_post_meta(get_the_ID(),'_nvconsult_salary_range',true); $apply=get_post_meta(get_the_ID(),'_nvconsult_apply_url',true); $visa=get_post_meta(get_the_ID(),'_nvconsult_visa_sponsored',true); ?><article class="job-card"><div class="job-card__image"><?php if(has_post_thumbnail()): the_post_thumbnail('large'); endif; ?></div><div class="job-card__body"><?php if($visa): ?><span class="visa-badge"><?php esc_html_e( 'Visa Sponsored', 'nvconsult-theme-v2' ); ?></span><?php endif; ?><h3><?php the_title(); ?></h3><?php if($location): ?><p><?php echo esc_html( $location ); ?></p><?php endif; ?><?php if($salary): ?><p><strong><?php echo esc_html( $salary ); ?></strong></p><?php endif; ?><a class="btn-outline" href="<?php echo esc_url( $apply ? $apply : get_permalink() ); ?>"><?php esc_html_e( 'Apply Now →', 'nvconsult-theme-v2' ); ?></a></div></article><?php endwhile; wp_reset_postdata(); ?></div><p style="margin-top:24px;"><a class="btn-primary" href="<?php echo esc_url( get_post_type_archive_link( 'nvconsult_job' ) ); ?>"><?php esc_html_e( 'View All Opportunities →', 'nvconsult-theme-v2' ); ?></a></p><?php else: ?><div class="placeholder-message"><?php esc_html_e( 'Add jobs in wp-admin → Jobs to feature opportunities here.', 'nvconsult-theme-v2' ); ?></div><?php endif; ?></div></section>
